import json
from pathlib import Path
D=[]
M='https://learn.microsoft.com/en-us/'
def sources(*items): return [{'title':t,'url':M+u} for t,u in items]
def Q(id,n,stem,opts,ans,exp,take,src,typ='single',code=None):
 d={'id':f'{id}-q{n}','type':typ,'difficulty':'Analyze' if typ!='single' else 'Apply','stem':stem,'options':opts,'answer':ans,'explanations':exp,'takeaway':take,'source':M+src}
 if code:d['code']=code
 return d
def add(id,title,sub,tags,intro,sections,remember,pitfalls,lab,src,qs,priority='Core'):
 D.append({'id':id,'domain':'manage','title':title,'subtitle':sub,'minutes':18,'priority':priority,'tags':tags,'intro':intro,'sections':[{'title':t,'body':b,**({'code':c} if c else {})} for t,b,c in sections],'remember':remember,'pitfalls':pitfalls,'lab':{'title':lab[0],'steps':lab[1],'done':lab[2]},'sources':src,'questions':qs})
id='platform-architecture'
add(id,'Sentinel, Defender XDR, and the security data platform','Choose the right layer for ingestion, detection, investigation, and historical analysis.',['Architecture','Content hub','Data lake'],
'''SC-200 scenarios often describe a requirement rather than name the feature that satisfies it. Start by drawing a data path: source, ingestion, table, detection, incident, response. Microsoft Sentinel supplies SIEM coverage for Microsoft, third-party, cloud, and on-premises sources. Defender XDR correlates signals from deployed Defender workloads. The Defender portal brings those workflows together, while the Sentinel data lake adds economical historical analysis and graph capabilities. A unified screen does not remove the need to configure connectors, permissions, tables, and response resources. Learn what each layer contributes so you can identify the missing prerequisite instead of choosing a familiar product name.''',[
('Build the operational path','''A Log Analytics workspace becomes a Sentinel workspace when Sentinel is enabled on it. Start with the workspace region, access model, retention needs, and data sources. A connector makes a supported source available, but the source may still need diagnostic settings, an agent, API credentials, or collection configuration. Inspect the connector instructions and destination tables. An installed solution packages useful content; it does not prove telemetry is arriving. For a firewall investigation, verify actual recent records before enabling a detection that expects them. A successful deployment and a successful data flow are different checkpoints.''',None),
('Use the unified portal deliberately','''Connecting Sentinel workspaces to the Defender portal enables combined incident handling and hunting with Defender XDR where those services are deployed. A tenant can have a primary Sentinel workspace and connected secondary workspaces. Select the intended workspace and check its connection state when a feature appears empty. Portal access does not itself grant every Azure or Defender permission. Sentinel can be used in the Defender portal without purchasing an XDR license simply for that portal experience. Product-specific telemetry and response actions still depend on their own deployment, licensing, configuration, and permissions.''',None),
('Understand the lake and graph layer','''The Sentinel data lake separates long-term storage from the compute used to analyze it. Analytics data supports operational detection and interactive investigation; lake-only data serves historical analysis through the supported lake query, job, and notebook experiences. Graph uses relationships and asset context to help investigate connected risk. Onboarding requires a connected primary workspace and appropriate setup roles; choose the supported region and billing resources carefully. For the exam, distinguish adding a workspace to the portal from completing lake onboarding. Neither operation magically supplies missing endpoint, identity, or third-party telemetry.''',None),
('Move from content to validated capability','''Content hub is the starting point for packaged connectors, workbook templates, analytics templates, and automation content. Install the relevant solution, configure its connector, validate tables, and then create active content from templates. Templates require adaptation to your environment, including entity mapping and exceptions. Track updates and verify that customizations still behave correctly. When a scenario says an analyst installed a solution but has no incidents, ask whether data arrived, the rule was activated, its query returned results, and its incident settings permit incident creation. This sequence is more reliable than reinstalling everything.''',None)],
['Sentinel workspace, Defender portal connection, and lake onboarding are distinct steps.','A content template is not necessarily an active rule or saved workbook.','A unified portal still uses the permissions and deployment prerequisites of underlying products.'],
['Do not assume Defender XDR automatically collects every third-party log.','Do not assume lake-only storage supports every real-time SIEM feature.'],
('Trace one complete detection path',['Use a training or test Sentinel workspace and identify its region and portal connection.','Install one Microsoft solution from Content hub and read its connector prerequisites.','Find a recent row in the documented destination table.','Open the related detection template and list what must be configured before activation.'],'You can trace one real event from source to destination table and explain how a rule would create an incident.'),
sources(('Onboard to Microsoft Sentinel','azure/sentinel/quickstart-onboard'),('Connect Sentinel to the Defender portal','unified-secops/microsoft-sentinel-onboard'),('Sentinel data lake overview','azure/sentinel/datalake/sentinel-lake-overview'),('Deploy out-of-the-box content','azure/sentinel/sentinel-solutions-deploy'),('Onboard the Sentinel data lake','azure/sentinel/datalake/sentinel-lake-onboard-defender')),[
Q(id,1,'A SOC installed a firewall solution from Content hub. Its analytics template exists, but no firewall records appear in the destination table. What should the engineer do first?',['Enable every analytics template.','Configure and validate the solution’s data connector and source forwarding.','Increase incident retention.','Create a graph query to generate missing logs.'],[1],['A query cannot detect records that were never ingested.','Correct. Validate the source-to-table ingestion path before troubleshooting detection behavior.','Retention preserves existing records; it does not collect absent logs.','A relationship query analyzes available data and cannot replace source ingestion.'],'Check ingestion before detection configuration.','azure/sentinel/quickstart-onboard'),
Q(id,2,'A tenant needs unified incident handling and economical historical analysis. Choose TWO distinct configuration steps that directly enable these experiences.',['Connect the Sentinel workspace to the Defender portal.','Replace all source connectors with workbook templates.','Complete Sentinel data lake onboarding with the required roles and billing resources.','Grant every analyst Global Administrator permanently.'],[0,2],['Correct. Connecting the workspace enables the unified Sentinel portal experience.','Workbooks visualize data; they do not replace connectors.','Correct. Lake onboarding enables the additional lake experiences.','Broad permanent access is unnecessary and does not provision the required platform.'],'Portal connection and lake onboarding solve different requirements.','azure/sentinel/datalake/sentinel-lake-onboard-defender','multi'),
Q(id,3,'An organization needs to retain rarely consulted network telemetry for later historical analysis. It does not require real-time alerts on that data. Which design best matches the requirement?',['Keep every record only in a workbook JSON resource.','Use lake-only storage and supported lake queries or jobs for the historical investigation.','Delete the source data after each analytics rule run.','Use an alert email mailbox as the primary log store.'],[1],['A saved workbook stores its definition, not a copy of its query results as a security log repository.','Correct. The lake is designed for cost-conscious historical data analysis where operational real-time features are unnecessary.','Deleting evidence prevents the required later investigation.','Notifications contain selected alert details rather than the complete source telemetry.'],'Storage tier follows operational access and detection needs.','azure/sentinel/datalake/sentinel-lake-overview'),
Q(id,4,'Arrange the normal rollout of packaged Sentinel detection content after selecting the product integration.',['Validate recent records in the expected table.','Create and tune an active analytics rule from its template.','Install the product solution from Content hub.','Configure connector prerequisites and source forwarding.'],[2,3,0,1],['Validation follows collection setup and establishes that the rule has input.','Activate and tune after the required input has been verified.','Install the content package first to obtain the supported connector and templates.','Configure the actual ingestion path before expecting records.'],'Install, connect, validate, then detect.','azure/sentinel/sentinel-solutions-deploy','order')])
id='sentinel-rbac'
add(id,'Sentinel RBAC and playbook permissions','Separate analyst access, engineering rights, workflow authoring, and service execution.',['RBAC','Least privilege','Logic Apps'],
'''Permission questions become manageable when you identify the actor, action, resource, and scope. Reading an incident, changing a rule, editing a Logic App, and letting Sentinel invoke a playbook are separate operations. A role that is sufficient for one need might intentionally omit another. SC-200 expects you to choose a workable combination with limited privilege and to diagnose why an existing assignment fails. Also distinguish Azure RBAC on the SIEM workspace from Microsoft Entra and Defender permission models used by the wider platform. A person’s permissions are not automatically the permissions of Sentinel’s service identity or a playbook’s managed identity.''',[
('Assign analyst and engineer roles','''Sentinel Reader supports viewing Sentinel resources and data. Responder adds incident management, such as assignment and status changes. Contributor adds creation and editing of Sentinel resources such as analytics rules and content management. Choose the least powerful role that supports the actual task. A triage analyst who must resolve incidents generally needs Responder rather than Reader; an engineer editing detections needs Contributor. Role scope matters as much as the name. Resource-group assignments commonly cover the workspace and associated resources more predictably than assigning permissions to a single object and overlooking related resources.''',None),
('Keep workflow authority separate','''Playbooks are Azure Logic Apps resources. Sentinel Contributor does not, by itself, grant Logic Apps authoring rights. Use Logic App Contributor when a person must create or modify the workflow. A person who only lists and manually runs playbooks can use Sentinel Playbook Operator alongside the access needed to open the incident. When a run is unavailable, verify the workflow trigger, location, and permissions rather than adding subscription Owner reflexively. An account can have enough authority to change an incident while having no authority to edit the workflow attached to it.''',None),
('Check service and connector identities','''Sentinel uses its own service account to execute incident playbooks. That identity needs Sentinel Automation Contributor on the resource group containing the playbook. An administrator with role-assignment authority grants this access; granting the human Contributor on the workspace does not substitute for it. The workflow then calls target systems through connector connections or managed identities, which need their own target permissions. For example, permission to start an enrichment workflow does not automatically authorize its identity to read secrets. Troubleshoot execution permission and downstream API authorization as separate stages in run history.''',None),
('Understand scope and cumulative access','''Azure role assignments are additive. Assigning Reader cannot reduce rights inherited from Contributor at a parent scope. Review inherited assignments when access appears broader than intended. For workspace logs, distinguish workspace-wide access from supported resource-context access and table controls. Lake-wide roles can be broader than a workspace-only analyst requires; the current platform supports scoped workspace read access and separate system-table permissions. Ask which workspace, data collection, or resource the person needs before choosing a role. For an exam scenario, a correct role at the wrong scope is still an incomplete configuration.''',None)],
['Responder manages incidents; Contributor engineers Sentinel resources.','Logic App Contributor is for workflow authoring; Playbook Operator supports manual execution.','Sentinel’s service identity needs Automation Contributor on the playbook resource group.','Inherited Azure RBAC permissions are cumulative.'],
['Automation Contributor is a service permission, not the normal analyst role.','A workflow’s downstream connector authorization is separate from permission to start it.'],
('Map permissions without broad elevation',['Create an actor/action/resource matrix for a triage analyst, detection engineer, Sentinel service, and playbook identity.','Inspect effective assignments at workspace and resource-group scopes in a test tenant.','Check playbook permissions and one connector identity.','Explain a failed run using both invocation permission and target API authorization.'],'Your permission map grants each actor only the operations needed and identifies both execution and connector dependencies.'),
sources(('Roles and permissions in Sentinel','azure/sentinel/roles'),('Built-in security roles','azure/role-based-access-control/built-in-roles/security'),('Manage Sentinel access by resource','azure/sentinel/resource-context-rbac'),('Run Sentinel playbooks','azure/sentinel/automation/run-playbooks')),[
Q(id,1,'A tier-one analyst must assign and close Sentinel incidents but must not edit analytics rules. What is the minimum appropriate built-in Sentinel role?',['Reader','Responder','Contributor','Automation Contributor'],[1],['Reader can inspect resources but cannot perform the required incident changes.','Correct. Responder adds incident management while avoiding detection-authoring rights.','Contributor works but grants unnecessary ability to modify Sentinel resources.','This role enables Sentinel service execution of playbooks; it is not the incident analyst role.'],'Use Responder for operational incident management.','azure/sentinel/roles'),
Q(id,2,'A responder can open an incident but cannot manually run its existing incident playbook. The person must not edit workflows. Choose TWO permission checks.',['Verify the person has Sentinel Playbook Operator over the playbook resource group.','Verify Sentinel’s service account has Automation Contributor over that resource group.','Assign the person Logic App Contributor so all workflow edits are allowed.','Assign Automation Contributor only to the person and remove all service permissions.'],[0,1],['Correct. This grants the human the intended manual run capability.','Correct. Incident-trigger playbook execution also relies on the Sentinel service identity’s explicit permission.','Workflow authoring is beyond the stated requirement.','The human assignment does not replace the service identity requirement.'],'Manual incident execution can involve both user and service permissions.','azure/sentinel/automation/run-playbooks','multi'),
Q(id,3,'An engineer has Sentinel Contributor on the workspace. They can change analytics rules but cannot edit an existing playbook in another resource group. Which additional role directly addresses the missing capability?',['Logic App Contributor on the playbook’s resource group.','Sentinel Reader on the workspace.','Directory Reader on the tenant.','Sentinel Automation Contributor on the engineer’s user account.'],[0],['Correct. The missing operation is authoring a Logic App at its actual resource scope.','Reader adds no workflow write capability.','Directory visibility does not authorize Azure Logic Apps editing.','Automation Contributor is intended for the Sentinel service to execute automation, not for workflow authoring.'],'Identify the resource being edited before choosing its role.','azure/sentinel/roles'),
Q(id,4,'A user inherits Contributor on a subscription and receives Reader directly on one workspace. They can still modify resources. What best explains this?',['The Reader assignment requires a restart.','Azure RBAC combines applicable grants; Reader does not negate inherited Contributor.','Sentinel ignores all direct workspace role assignments.','Every workspace user automatically becomes Owner.'],[1],['Role propagation does not turn a Reader grant into a deny against a broader grant.','Correct. Remove or narrow the broader assignment if reduced access is intended.','Direct assignments are relevant, but do not cancel parent grants.','Workspace membership does not automatically assign ownership.'],'Least privilege requires reviewing effective inherited access.','azure/role-based-access-control/built-in-roles/security')])
id='windows-ama-wef'
add(id,'Windows Security Events, AMA, and WEF','Select the collection path, DCR, and destination table your detections actually need.',['AMA','DCR','WEF','SecurityEvent'],
'''An empty Windows detection is frequently an ingestion or table mismatch rather than a faulty query. Windows Security Events via Azure Monitor Agent writes security events to SecurityEvent. Windows Event Forwarding centralizes selected events at a Windows Event Collector, where AMA can ingest them through the Windows Forwarded Events connector into WindowsEvent. Generic Azure Monitor Windows event collection can use Event instead. These distinctions are exam-relevant because many built-in Sentinel rules query a specific table. Learn the collection path, the association that targets machines, the event filter, and the table schema before tuning a threshold or assuming forwarding failed.''',[
('Choose direct AMA collection','''Use the Windows Security Events via AMA connector when machines can run the supported agent and you want Sentinel’s SecurityEvent-oriented security content. Non-Azure servers generally need Azure Arc integration for this extension-based collection path. A data collection rule defines what to collect and the workspace destination. A data collection rule association determines which machines use the rule. Installing an agent alone does not mean that the intended DCR applies. Validate the machine identity, association, event generation, network access, and destination before concluding that Sentinel is dropping an event.''',None),
('Filter events where it makes sense','''Common, Minimal, All, and custom selections represent different coverage and volume decisions. Minimal is not a promise of a complete audit trail. With custom XPath, choose the correct channel and event identifiers; test the expression against actual event data. An event filter cannot create records that audit policy never generates on the source. Align the selected event set with the analytics templates and investigation requirements. For example, excluding logon failure records undermines a password-spray use case even if the agent and workspace connection are healthy. Reducing ingestion should preserve the evidence your detections need.''',None),
('Plan WEF and WEC as a separate hop','''WEF forwards selected source events to a Windows Event Collector. Source-initiated subscriptions can be distributed through Group Policy, and source audit policy and channel access must permit the expected collection. The collector runs the Windows Event Collection service and AMA for the Sentinel connection. This architecture can meet a requirement that individual sources cannot each host the monitoring agent. Check both hops: source to WEC, then WEC to Azure. Seeing events on the collector proves only the first hop. Examine collector capacity, subscription health, and the DCR when planning scale or troubleshooting missing data.''',None),
('Validate the correct table and fields','''The Windows Forwarded Events connector stores events in WindowsEvent, including forwarded Security-channel events. It does not automatically populate SecurityEvent. A built-in rule reading SecurityEvent therefore needs a compatible ingestion path or an adapted query and mapping. Generic Azure Monitor event collection can instead populate Event. Query recent counts by computer and event identifier, inspect a sample event, and check the timestamps. Schema-aware parsers help normalize fields across sources, but a parser is not a forwarding configuration. Always match the connector’s destination schema with the detection query before enabling production alerting.''',None)],
['DCR defines collection; DCR association targets the machine.','Windows Security Events via AMA → SecurityEvent.','Windows Forwarded Events → WindowsEvent; generic Windows events can use Event.','Audit policy controls whether the source produces the desired event.'],
['Events visible at WEC do not prove ingestion to Sentinel.','Security-channel origin does not guarantee the SecurityEvent destination table.'],
('Compare direct and forwarded records',['In an official training lab, inspect a Windows Security Events via AMA DCR and machine association.','Generate or identify a known permitted Security event and locate it in SecurityEvent.','Inspect a WEF subscription and its collector ForwardedEvents channel.','Compare the WindowsEvent schema against a SecurityEvent-based rule before adapting the query.'],'You can identify both transport hops and explain exactly which table a detection must query.'),
sources(('Windows agent-based connectors','azure/sentinel/connect-services-windows-based'),('Windows security event sets','azure/sentinel/windows-security-event-id-reference'),('Collect Windows events using AMA','azure/azure-monitor/vm/data-collection-windows-events'),('Use WEF for intrusion detection','windows/security/operating-system-security/device-management/use-windows-event-forwarding-to-assist-in-intrusion-detection')),[
Q(id,1,'A new WEF deployment shows Security events in the collector’s ForwardedEvents channel and in WindowsEvent. A built-in Sentinel rule queries SecurityEvent and returns no matches. What is the best next step?',['Reinstall WEC because forwarding must have failed.','Adapt and test the rule for WindowsEvent, or use the Windows Security Events via AMA path required by the existing content.','Increase the threshold so the missing rows become visible.','Rename WindowsEvent to SecurityEvent in the workspace.'],[1],['The collector and WindowsEvent evidence demonstrate successful forwarding and ingestion.','Correct. The rule and ingestion path use different destination schemas.','A threshold does not repair a table mismatch.','Managed table naming is not a substitute for choosing a supported connector or adapting a query.'],'The destination schema matters more than the source channel name.','azure/sentinel/connect-services-windows-based'),
Q(id,2,'A supported Azure VM has AMA installed but no expected logon failure records arrive. Choose TWO checks that directly address collection configuration.',['Confirm the intended DCR is associated with this VM.','Confirm audit policy generates the event and the DCR XPath includes it.','Grant the analyst workbook editing permissions.','Create an incident automation rule that renames the VM.'],[0,1],['Correct. The installed agent needs the intended rule association.','Correct. Both source generation and event filtering must permit the record.','Workbook authoring rights do not control agent collection.','Incident automation acts after detection; it cannot generate missing source logs.'],'Validate source generation, filtering, and rule association.','azure/azure-monitor/vm/data-collection-windows-events','multi'),
Q(id,3,'A policy prevents installing AMA on each branch Windows server, but permits built-in Windows event forwarding and an agent on a central collector. Which design fits?',['Install AMA only on analyst laptops.','Use WEF subscriptions to a WEC server, then AMA and the Windows Forwarded Events connector on the collector.','Use a CEF connector to query each Windows Security channel directly.','Use workbook auto-refresh to pull events from the branch servers.'],[1],['Analyst laptops do not become collectors simply by having the agent.','Correct. WEF centralizes the first hop and AMA handles the collector-to-workspace hop.','CEF is not a native direct subscription to Windows event channels.','A workbook reads ingested data rather than replacing event transport.'],'Use WEF when the collector can host the agent but sources cannot.','windows/security/operating-system-security/device-management/use-windows-event-forwarding-to-assist-in-intrusion-detection'),
Q(id,4,'A team selects the Minimal event set to reduce volume. Later it needs a complete Windows audit trail. Which conclusion is accurate?',['Minimal guarantees all audit events needed by any investigation.','Minimal is a selected subset; review audit policy and expand collection to meet the complete evidence requirement.','Switching to Minimal automatically enables every source audit category.','A longer workbook time range reconstructs excluded events.'],[1],['Minimal intentionally omits events and cannot promise complete auditing.','Correct. Coverage must be designed against the evidence requirement rather than the collection preset’s name.','A connector filter and source audit generation are separate controls.','Query time ranges cannot recover events that were never ingested.'],'Collection presets trade coverage against volume.','azure/sentinel/windows-security-event-id-reference')])
id='syslog-cef'
add(id,'Syslog and CEF through Azure Monitor Agent','Trace appliance logs through a Linux forwarder, DCR filtering, and the right table.',['Syslog','CEF','AMA','CommonSecurityLog'],
'''Network appliances often cannot run AMA themselves. A Linux forwarder receives their Syslog traffic, and AMA sends selected messages onward to the workspace. CEF adds a structured event format on top of the transport so Sentinel can populate normalized CommonSecurityLog fields; ordinary Syslog commonly lands in Syslog. SC-200 can test connector choice, forwarding prerequisites, filtering, duplicate ingestion, and failure isolation. Follow the message through each boundary instead of assuming that an open network port proves the entire integration works. Source formatting, local daemon behavior, rule association, facility and severity selection, and cloud connectivity can each break a different part of the path.''',[
('Select format and collector architecture','''Syslog is the transport and message ecosystem; CEF is a security event format that can be carried by Syslog. A CEF header identifies vendor, product, event class, and severity, followed by extension fields. Use the CEF via AMA connector for compatible security appliance output and expect CommonSecurityLog. Use Syslog via AMA for ordinary Syslog and expect Syslog. The forwarder is a supported Linux machine with rsyslog or syslog-ng and AMA. When it is outside Azure, check the Azure Arc prerequisite. Install the relevant solution and follow the vendor’s appliance configuration instructions.''',None),
('Configure both network boundaries','''The appliance sends to the Linux daemon’s configured listening address, port, and transport. The daemon then forwards selected messages to AMA, which uses outbound connectivity to Azure. These are different connections; allowing appliance traffic alone does not authorize cloud egress. Confirm the daemon is listening on the interface that the appliance can reach, and verify actual received messages with an approved test or packet capture. Then verify the daemon-to-agent handoff and agent health. Use the documented current agent configuration rather than assuming a port from an older blog still applies.''',None),
('Make the DCR match the intended logs','''A data collection rule chooses facilities, severities, destinations, and associated forwarders. A severity threshold includes that severity and more serious levels; debug is more verbose than error. A facility mismatch can silently exclude an otherwise well-formed message. Distinguish the Syslog severity used by collection filtering from a security product’s own event severity field. If the same facility is collected through overlapping Syslog and CEF rules, investigate duplicate collection and separate the selections where needed. Reducing noise is useful only if you can show that required firewall or authentication events still arrive.''',None),
('Troubleshoot with evidence from each hop','''Begin at the appliance: confirm output format, destination, and a recent event. On the forwarder, confirm network arrival, daemon handling, and valid CEF syntax when using that connector. Check pipe delimiters and required escaping in CEF headers and extension values. Next inspect AMA operation, the DCR association, filtering, and destination workspace. Finally query the expected table by a narrow time range and host or vendor. If Syslog arrives but parsed CEF fields do not, focus on format and connector routing before rebuilding the whole agent. Keep troubleshooting changes temporary and return filters to the required scope.''',None)],
['CEF via AMA normally populates CommonSecurityLog; Syslog via AMA populates Syslog.','Appliance → Linux daemon → AMA → workspace are separate checkpoints.','Facility and severity filters must include the actual source messages.','Avoid overlapping rules that ingest the same traffic twice.'],
['CEF event severity and Syslog transport severity are different fields.','A listening forwarder does not prove AMA can reach Azure.'],
('Trace a controlled Syslog event',['Use a test Linux forwarder with a documented AMA connector and DCR.','Record the configured facility, severity, transport, and listening port.','Send a harmless approved test message from a permitted source.','Verify its arrival locally and then in the correct destination table.','Compare one valid CEF message with ordinary Syslog fields.'],'You can name the failing hop when local receipt succeeds but workspace ingestion does not.'),
sources(('Syslog and CEF architecture','azure/sentinel/cef-syslog-ama-overview'),('Ingest Syslog and CEF using AMA','azure/sentinel/connect-cef-syslog-ama'),('Collect Syslog using AMA','azure/azure-monitor/vm/data-collection-syslog'),('Troubleshoot Syslog and CEF connectors','azure/sentinel/cef-syslog-ama-troubleshooting')),[
Q(id,1,'A firewall emits correctly formatted CEF over Syslog. Analysts need parsed source and destination fields in Sentinel’s standard security-event table. Which connector and table should they select?',['Syslog via AMA and Event.','CEF via AMA and CommonSecurityLog.','Windows Forwarded Events and SecurityEvent.','Azure Activity and AzureActivity.'],[1],['Event is not the ordinary Syslog connector’s destination, and this does not select the CEF parsing path.','Correct. CEF collection maps supported fields into CommonSecurityLog.','This Windows collection path does not ingest the appliance CEF feed.','Azure Activity contains Azure control-plane operations, not the firewall’s CEF stream.'],'Match the wire format to its connector and schema.','azure/sentinel/cef-syslog-ama-overview'),
Q(id,2,'The Linux forwarder receives a test message, but no row reaches Sentinel. Choose TWO useful next checks after local receipt has been proven.',['Verify AMA health, DCR association, and destination workspace.','Verify the DCR includes the message’s facility and severity.','Change incident ownership to the network team.','Increase the workbook chart height.'],[0,1],['Correct. These components govern the remaining agent-to-cloud path.','Correct. A filter can exclude a locally received message.','Ownership affects case workflow after ingestion and detection.','Display settings have no effect on transport or collection.'],'Local receipt narrows troubleshooting to downstream collection and routing.','azure/sentinel/cef-syslog-ama-troubleshooting','multi'),
Q(id,3,'An appliance sends informational messages using local4. A DCR collects local5 at error and above. The network path is healthy. What should be changed to collect the intended informational events?',['Only increase retention.','Select local4 and an appropriate informational-or-more-verbose collection threshold.','Keep local5 and change the analytics incident title.','Convert every informational message into a critical security alert at the source.'],[1],['Retention cannot affect which incoming messages are selected.','Correct. Both the facility and the severity selection currently exclude the target events.','Incident naming does not fix collection filters.','Changing event meaning is unnecessary; collect the required messages accurately.'],'A valid message still needs to match facility and severity selection.','azure/azure-monitor/vm/data-collection-syslog'),
Q(id,4,'Place these validation steps in source-to-destination order for a CEF integration.',['Confirm the record in CommonSecurityLog with expected parsed fields.','Confirm the appliance sends valid CEF to the intended destination.','Verify the Linux daemon receives and hands the message to AMA.','Verify the associated DCR allows the event and routes it to the workspace.'],[1,2,3,0],['The final table check proves that all earlier stages worked together.','Start by establishing that the source emitted the intended format.','The collector is the next physical and logical hop.','The agent’s rule and destination determine cloud routing after local receipt.'],'Troubleshoot each boundary in the actual direction of data flow.','azure/sentinel/connect-cef-syslog-ama','order')])
id='azure-custom-ingestion'
add(id,'Azure diagnostics and custom log ingestion','Use policy for scale and DCR-based schemas for custom events.',['AzureActivity','Diagnostic settings','DCR','Custom tables'],
'''A cloud resource can exist without its security-relevant logs appearing in Sentinel. Azure Activity captures management operations, resource logs capture service-specific operations, and custom applications may require a dedicated ingestion path. SC-200 scenarios ask you to choose the right mechanism, deploy it consistently, and troubleshoot the missing link. Understand the distinction between a diagnostic setting and an agent rule, and between a table definition and the API that supplies rows. For custom ingestion, think of the DCR as a contract: incoming stream schema, optional transformation, destination workspace, and output table must agree. Correct authentication alone cannot repair an incompatible schema.''',[
('Separate control plane from data plane','''Azure Activity records management-plane operations such as resource creation and configuration changes. Export the relevant subscription activity through diagnostic settings to the Sentinel workspace and query AzureActivity. Resource logs describe operations inside a service, such as a Key Vault secret access, and typically require that resource’s diagnostic settings. A subscription Activity log export does not automatically collect every resource’s data-plane audit stream. In a scenario, identify what the attacker actually did before selecting the source. Reading a secret and changing a vault’s resource configuration require different evidence even though both involve the same vault.''',None),
('Use Azure Policy for coverage at scale','''Diagnostic settings specify which log categories or category groups are sent to destinations such as Log Analytics, Event Hubs, or Storage. Azure Policy can enforce or deploy appropriate settings across many resources or subscriptions. A deployIfNotExists assignment uses its managed identity and required permissions; existing noncompliant resources can require a remediation task. Scope the policy to the intended environment and verify the destination workspace parameter. Policy compliance means the expected configuration exists, so still verify fresh records. A mistaken workspace selection can produce an apparently healthy deployment while the SOC continues querying a different workspace.''',None),
('Define the custom ingestion contract','''Create a custom table with the required column names and types, including TimeGenerated. Custom table names use the _CL suffix. A DCR stream declaration describes the incoming shape; a data flow selects that stream, applies any supported transformation, and sends the transformed output to a destination. The output stream names the target table. Use the DCR ingestion endpoint or a data collection endpoint as required by the current architecture, including private-link requirements. An Entra application sending through the Logs Ingestion API needs authorized access to the DCR; this is not the same as possessing a workspace shared key.''',None),
('Transform and validate before activation','''Use an ingestion transformation to parse, rename, cast, or filter supported incoming data so the output matches the destination schema. The transformation uses the source input, and its output must include the required columns in their expected types. Verify the DCR immutable identifier and stream name used by the client, its token audience and role assignment, network reachability, and returned error details. Then query a known test event in the custom table. A successful HTTP submission is one checkpoint; inspect the row’s timestamp, parsed fields, and workspace before allowing detections to depend on it.''',None)],
['AzureActivity is control-plane evidence; resource logs capture service-specific data-plane events.','Policy can deploy diagnostic settings; existing resources may need remediation.','DCR stream schema, transformation output, destination, and table schema must agree.','Logs Ingestion API uses Entra authorization on the DCR.'],
['A custom table definition does not itself ingest any rows.','Activity log export does not replace Key Vault resource audit logging.','A DCR immutable ID is different from a workspace ID.'],
('Validate a small custom stream',['Create a test custom table using Microsoft’s Logs Ingestion API tutorial and record its schema.','Inspect the DCR input stream, transformation, destination, and output stream.','Authorize the test application narrowly and submit a harmless synthetic event.','Query by its unique test identifier and inspect TimeGenerated and parsed columns.','Inspect a diagnostic-settings policy assignment and an existing-resource remediation task.'],'You can prove which source, DCR, workspace, and table contain your test event.'),
sources(('Azure Activity log','azure/azure-monitor/fundamentals/activity-log'),('Diagnostic settings','azure/azure-monitor/data-collection/diagnostic-settings'),('Deploy diagnostic settings with Policy','azure/azure-monitor/data-collection/diagnostic-settings-policy'),('Logs Ingestion API overview','azure/azure-monitor/logs/logs-ingestion-api-overview'),('DCR structure','azure/azure-monitor/data-collection/data-collection-rule-structure'),('Create custom tables','azure/azure-monitor/logs/create-custom-table')),[
Q(id,1,'An investigator needs evidence that an administrator changed a virtual network configuration. Which source should be exported to Sentinel for this control-plane operation?',['Azure Activity log.','Only the VM’s process-creation events.','Only firewall packet payload logs.','A workbook template with no data connection.'],[0],['Correct. Resource management changes are Azure Activity control-plane events.','Process telemetry does not establish the Azure Resource Manager operation.','Traffic logs describe data traffic rather than who changed the Azure resource configuration.','A visualization template does not generate audit evidence.'],'Select logs based on the operation being investigated.','azure/azure-monitor/fundamentals/activity-log'),
Q(id,2,'A policy must deploy required diagnostic settings to new resources and repair existing noncompliant resources. Choose TWO implementation requirements.',['Provide the policy assignment’s managed identity the required deployment permissions.','Run an appropriate remediation task for existing noncompliant resources.','Give every log reader permission to change policy assignments.','Rely on workbook refresh to create diagnostic settings.'],[0,1],['Correct. Deployment policy needs an identity authorized to make the required change.','Correct. Existing resources commonly require remediation after assignment.','Readers do not need policy-authoring authority to consume logs.','Refresh runs visualization queries and does not deploy source settings.'],'Policy scope, identity, and remediation together support scaled configuration.','azure/azure-monitor/data-collection/diagnostic-settings-policy','multi'),
Q(id,3,'A Logs Ingestion API client authenticates successfully, but submitted data fails schema validation. The input contains EventTime as a string while the destination requires TimeGenerated as datetime. What should the engineer inspect?',['The DCR stream declaration and transformation that produces the destination schema.','Incident grouping settings only.','The analyst’s email notification rules.','The workbook’s color palette.'],[0],['Correct. Input schema and output transformation must yield the table’s expected names and types.','Incident grouping occurs after ingestion and does not alter the API contract.','Notifications do not transform incoming rows.','Display settings have no bearing on schema validation.'],'A valid token and a valid data contract solve different problems.','azure/azure-monitor/data-collection/data-collection-rule-structure'),
Q(id,4,'A company already exports subscription Activity logs. It now needs to investigate individual Key Vault secret reads. What additional configuration is appropriate?',['Enable the relevant Key Vault resource diagnostic audit logs to the workspace.','Increase the Activity log chart’s refresh rate.','Query AzureActivity and assume all secret contents are recorded there.','Rename the AzureActivity table.'],[0],['Correct. Secret access is a service data-plane operation captured through the relevant resource logs.','Refreshing cannot create an uncollected event type.','Activity log is management-plane evidence, not a complete record of service data-plane reads.','Renaming a table neither changes its source nor creates missing audit data.'],'Management-plane and data-plane logging must be planned separately.','azure/azure-monitor/data-collection/diagnostic-settings')])
